	("2.In cea de-a doua casuta din inventar pune-ti Vrajeste Obiectul", "2. Put the Enchant Item in the second slot"),
	("Buzlu kayalar\xfdn alt\xfdndaki kadim ma\xf0aran\xfdn m\xfch\xfcrl\xfc giri\xfe kap\xfds\xfd.", "The sealed entrance of the ancient cave beneath the icy rocks."),
